<?php
include_once __DIR__.'/includes/session_check.php';require_login_modal();include __DIR__.'/db_connect.php';include_once __DIR__.'/includes/attendance_report_queries.php';
$school=(int)($_SESSION['login_school_id']??0);if(!$school)die('No autorizado.');$view=$_GET['view']??'detail';$f=arq_filters($conn,$school,$_GET);$result=arq_rows($conn,$school,$f,$view,0,1000);$summary=arq_summary($conn,$school,$f);$titles=['detail'=>'Detalle de marcaciones','student'=>'Resumen por estudiante','class'=>'Resumen por aula','incidents'=>'Incidencias','daily'=>'Control diario'];function aph($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}function apState($v){return in_array($v,['Normal','Temprano'])?'Presente':$v;}
?>
<style>.aprint{font-size:12px;color:#263754}.aprint h4{color:#263754}.aprint table{width:100%;border-collapse:collapse}.aprint th,.aprint td{border:1px solid #d8deea;padding:6px}.aprint th{background:#f1f4f9}.ap-kpis{display:flex;gap:8px;flex-wrap:wrap;margin:10px 0}.ap-kpis span{border:1px solid #d8deea;padding:7px 10px;border-radius:5px}.ap-actions{text-align:right;margin-bottom:10px}@media print{body *{visibility:hidden!important}.aprint,.aprint *{visibility:visible!important}.aprint{position:absolute;left:0;top:0;width:100%}.ap-actions{display:none!important}}</style>
<div class="aprint"><div class="ap-actions"><button class="btn btn-primary btn-sm" onclick="window.print()"><i class="fas fa-print mr-1"></i>Imprimir</button></div><h4><?php echo aph($titles[$view]??'Reporte de asistencia');?></h4><div class="text-muted">Periodo: <?php echo date('d/m/Y',strtotime($f['from'])).' al '.date('d/m/Y',strtotime($f['to']));?></div><div class="ap-kpis"><span>Marcaciones: <b><?php echo $summary['total'];?></b></span><span>Presentes: <b><?php echo $summary['present'];?></b></span><span>Tardanzas: <b><?php echo $summary['late'];?></b></span><span>Ausencias: <b><?php echo $summary['absent'];?></b></span><span>Asistencia: <b><?php echo $summary['attendance_rate'];?>%</b></span></div>
<table><thead><tr><?php if($view==='detail'):?><th>Fecha</th><th>Estudiante</th><th>Aula</th><th>Hora</th><th>Tipo</th><th>Estado</th><?php elseif($view==='daily'):?><th>Fecha</th><th>Aula</th><th>Marcados</th><th>Presentes</th><th>Tardanzas</th><th>Ausencias</th><th>Control</th><?php else:?><th><?php echo $view==='class'?'Aula':'Estudiante';?></th><th>Marcaciones</th><th>Presentes</th><th>Tardanzas</th><th>Ausencias</th><th>Justificadas</th><th>Permisos</th><?php endif;?></tr></thead><tbody>
<?php foreach($result['rows'] as $r):?><tr><?php if($view==='detail'):?><td><?php echo date('d/m/Y',strtotime($r['fecha']));?></td><td><?php echo aph($r['student_name']);?></td><td><?php echo aph($r['nivel'].' '.$r['grado'].' '.$r['seccion']);?></td><td><?php echo substr($r['hora'],0,5);?></td><td><?php echo aph($r['tipo']);?></td><td><?php echo aph(apState($r['estado']));?></td><?php elseif($view==='daily'):?><td><?php echo date('d/m/Y',strtotime($r['fecha']));?></td><td><?php echo aph($r['nivel'].' '.$r['grado'].' '.$r['seccion']);?></td><td><?php echo $r['marked'];?></td><td><?php echo $r['present'];?></td><td><?php echo $r['late'];?></td><td><?php echo $r['absent'];?></td><td><?php echo aph($r['closure_status']);?></td><?php else:?><td><?php echo aph($view==='class'?($r['nivel'].' '.$r['grado'].' '.$r['seccion']):($r['student_name'].' · '.$r['id_no']));?></td><td><?php echo $r['marks'];?></td><td><?php echo $r['present'];?></td><td><?php echo $r['late'];?></td><td><?php echo $r['absent'];?></td><td><?php echo $r['justified'];?></td><td><?php echo $r['permission'];?></td><?php endif;?></tr><?php endforeach;?></tbody></table><?php if($result['total']>1000):?><div class="alert alert-info mt-2">La vista previa muestra los primeros 1000 registros. El Excel contiene todos.</div><?php endif;?></div>
